	private static List<Q> read(Fixture fixture, Txn txn, boolean managed, String order, long context, Q seek)
			throws Exception {
		if (managed) {
			try (RecordIterator records = fixture.adjacency.scan(txn, -1, -1, -1, context, true, order)) {
				return seekAndCollect(records, seek);
			}
		}
		long stamp = txn.lockManager().readLock();
		try (RecordIterator records = fixture.adjacency.scan(txn.get(), -1, -1, -1, context, true, order)) {
			return seekAndCollect(records, seek);
		} finally {
			txn.lockManager().unlockRead(stamp);
		}
	}

	private static List<Q> seekAndCollect(RecordIterator records, Q seek) {
		if (seek != null) {
			assertThat(records.seekForward(seek.s, seek.p, seek.o, seek.c)).isTrue();
		}
		return collect(records);
	}

	private static List<Q> collect(RecordIterator records) {
		List<Q> result = new ArrayList<>();
		long[] quad;
		while ((quad = records.next()) != null) {
			result.add(Q.of(quad));
		}
		return result;
	}

	private static List<Q> expected(Iterable<Q> quads, String order, long context, Q minimum) {
		List<Q> result = new ArrayList<>();
		Comparator<Q> comparator = comparator(order);
		for (Q quad : quads) {
			if ((context == -1 || quad.c == context) && (minimum == null || comparator.compare(quad, minimum) >= 0)) {
				result.add(quad);
			}
		}
		result.sort(comparator);
		return result;
	}

	private static List<Q> after(Iterable<Q> quads, String order, Q first) {
		List<Q> result = expected(quads, order, -1, first);
		result.remove(first);
		return result;
	}

	private static Comparator<Q> comparator(String order) {
		return (left, right) -> {
			for (char field : order.toCharArray()) {
				int comparison = Long.compareUnsigned(left.component(field), right.component(field));
				if (comparison != 0) {
					return comparison;
				}
			}
			return 0;
		};
	}

	private static Q quad(int ordinal, long predicate) {
		return new Q(100 + 4L * ordinal, predicate, 10_000 + 4L * ordinal, ordinal % 3 == 0 ? 7 : 0);
	}

	private static Q gap(int ordinal, long predicate) {
		Q preceding = quad(ordinal, predicate);
		return new Q(preceding.s + 2, predicate, preceding.o + 2, 7);
	}

	private record Q(long s, long p, long o, long c) {
		static Q of(long[] quad) {
			assertThat(quad).isNotNull();
			return new Q(quad[0], quad[1], quad[2], quad[3]);
		}

		long component(char field) {
			return switch (field) {
			case 's' -> s;
			case 'p' -> p;
			case 'o' -> o;
			case 'c' -> c;
			default -> throw new AssertionError(field);
			};
		}
	}

