	private static final class CursorWork implements AutoCloseable {
		final MockedStatic<LMDB> calls;
		final Set<Long> live = new HashSet<>();
		long pageGets;
		long deltaGets;
		boolean sawPageNext;
		boolean injected;

		CursorWork(LmdbPersistentAdjacency adjacency, String failure) {
			calls = mockStatic(LMDB.class, invocation -> {
				String method = invocation.getMethod().getName();
				if (method.equals("mdb_cursor_get")) {
					long cursor = invocation.getArgument(0);
					int database = LMDB.mdb_cursor_dbi(cursor);
					int operation = invocation.getArgument(3);
					if (database == adjacency.pagesDbi()) {
						pageGets++;
						boolean fail = !injected && ("next".equals(failure) && operation == MDB_NEXT
								|| "restore".equals(failure) && sawPageNext && operation == MDB_SET_RANGE);
						sawPageNext |= operation == MDB_NEXT;
						if (fail) {
							injected = true;
							throw new IllegalStateException("injected page positioning failure");
						}
					} else if (database == adjacency.deltasDbi()) {
						deltaGets++;
					}
				} else if (method.equals("mdb_cursor_close")) {
					long cursor = invocation.getArgument(0);
					assertThat(live.remove(cursor)).as("a cursor is closed exactly once").isTrue();
				}
				Object result = invocation.callRealMethod();
				if (method.equals("mdb_cursor_open") && (int) result == 0) {
					PointerBuffer handle = invocation.getArgument(2);
					assertThat(live.add(handle.get(0))).isTrue();
				}
				return result;
			});
		}

		@Override
		public void close() {
			calls.close();
		}
	}
